# Index Health Monitor demo: freshness, coverage, smoke tests -> graded health.
import time
INDEX={"built":time.time()-4000,"records":{"r1","r2","r3"}}
SOURCE={"r1","r2","r3","r4"}
def check():
    issues=[]
    lag=time.time()-INDEX["built"]
    if lag>3600: issues.append(("stale","lag %.0fs"%lag))
    missing=SOURCE-INDEX["records"]
    if missing: issues.append(("incomplete","missing %s"%sorted(missing)))
    smoke=("r1" in INDEX["records"])
    if not smoke: issues.append(("failed","smoke test failed"))
    grade="healthy" if not issues else ("failed" if any(i[0]=="failed" for i in issues) else "lagging")
    return grade,issues
print(check())

